import { useEffect, useState } from "react";
import api from "../api";
import AddLevelWithTestCases from "../Admin/AddLevelWithTestCases";

export default function Problems() {
  const [problems, setProblems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);

  // 🔥 NEW
  const [showForm, setShowForm] = useState(false);

  useEffect(() => {
    loadProblems();

    const onResize = () => {
      setIsMobile(window.innerWidth < 768);
    };
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, []);

  const loadProblems = async () => {
    try {
      const res = await api.get("/problems");
      setProblems(res.data);
    } catch (err) {
      console.error("PROBLEMS ERROR:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Delete this problem?")) return;
    try {
      await api.delete(`/problems/${id}`);
      setProblems((prev) => prev.filter((p) => p.id !== id));
    } catch {
      alert("Delete failed");
    }
  };

  if (loading) {
    return <h2 style={styles.loading}>Loading problems...</h2>;
  }

  return (
    <div style={styles.container}>
      {/* HEADER */}
      <div style={styles.header}>
        <h2 style={styles.heading}>📘 Problems</h2>

        <button
          style={styles.addBtn}
          onClick={() => setShowForm((prev) => !prev)}
        >
          {showForm ? "❌ Close Form" : "➕ Add Problem"}
        </button>
      </div>

      {/* 🔥 ADMIN FORM */}
      {showForm && (
        <div style={{ marginBottom: 20 }}>
          <AddLevelWithTestCases />

          {/* reload list after adding */}
          <button
            style={{ ...styles.addBtn, marginTop: 10 }}
            onClick={() => {
              setShowForm(false);
              loadProblems();
            }}
          >
            🔄 Refresh List
          </button>
        </div>
      )}

      {/* LIST CARD */}
      <div style={styles.card}>
        {problems.length === 0 ? (
          <p style={styles.empty}>No problems found</p>
        ) : isMobile ? (
          /* ---------------- MOBILE VIEW ---------------- */
          <div style={styles.mobileList}>
            {problems.map((p) => (
              <div key={p.id} style={styles.mobileCard}>
                <div style={styles.mobileRow}>
                  <span style={styles.label}>Title</span>
                  <span>{p.title}</span>
                </div>

                <div style={styles.mobileRow}>
                  <span style={styles.label}>Difficulty</span>
                  <span
                    style={{
                      fontWeight: 700,
                      color:
                        p.difficulty === "Easy"
                          ? "#22c55e"
                          : p.difficulty === "Medium"
                          ? "#facc15"
                          : "#ef4444",
                    }}
                  >
                    {p.difficulty}
                  </span>
                </div>

                <div style={styles.mobileActions}>
                  <button style={styles.deleteBtn}
                    onClick={() => handleDelete(p.id)}
                  >
                    🗑 Delete
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          /* ---------------- DESKTOP TABLE ---------------- */
          <table style={styles.table}>
            <thead>
              <tr>
                <th style={styles.th}>ID</th>
                <th style={styles.th}>Title</th>
                <th style={styles.th}>Difficulty</th>
                <th style={styles.th}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {problems.map((p, index) => (
                <tr key={p.id} style={index % 2 ? styles.rowAlt : styles.row}>
                  <td style={styles.td}>{p.id}</td>
                  <td style={styles.td}>{p.title}</td>
                  <td
                    style={{
                      ...styles.td,
                      color:
                        p.difficulty === "Easy"
                          ? "#22c55e"
                          : p.difficulty === "Medium"
                          ? "#facc15"
                          : "#ef4444",
                      fontWeight: 600,
                    }}
                  >
                    {p.difficulty}
                  </td>
                  <td style={styles.td}>
                    <button
                      style={styles.deleteBtn}
                      onClick={() => handleDelete(p.id)}
                    >
                      🗑 Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

/* ---------------- STYLES ---------------- */

const styles = {
  container: {
    padding: "24px",
    background: "#0f172a",
    minHeight: "100vh",
  },
  header: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    marginBottom: "16px",
    gap: 10,
  },
  heading: {
    color: "#e5e7eb",
    fontSize: "22px",
  },
  addBtn: {
    background: "#22c55e",
    border: "none",
    color: "#020617",
    padding: "8px 14px",
    borderRadius: 8,
    cursor: "pointer",
    fontWeight: 600,
    whiteSpace: "nowrap",
  },
  loading: {
    color: "#e5e7eb",
    padding: 20,
  },
  card: {
    background: "#020617",
    borderRadius: 12,
    padding: 16,
    boxShadow: "0 10px 25px rgba(0,0,0,0.4)",
  },

  /* -------- DESKTOP TABLE -------- */
  table: {
    width: "100%",
    borderCollapse: "collapse",
  },
  th: {
    textAlign: "left",
    padding: "12px",
    background: "#020617",
    color: "#38bdf8",
    borderBottom: "1px solid #1e293b",
    fontSize: "14px",
    textTransform: "uppercase",
    letterSpacing: "0.05em",
  },
  td: {
    padding: "12px",
    borderBottom: "1px solid #1e293b",
    color: "#f1f5f9",
    fontSize: "14px",
  },
  row: {
    background: "#0f172a",
  },
  rowAlt: {
    background: "#020617",
  },

  /* -------- MOBILE CARDS -------- */
  mobileList: {
    display: "flex",
    flexDirection: "column",
    gap: 14,
  },
  mobileCard: {
    background: "#0f172a",
    borderRadius: 10,
    padding: 14,
    border: "1px solid #1e293b",
  },
  mobileRow: {
    display: "flex",
    flexDirection: "column",
    marginBottom: 8,
    fontSize: 14,
  },
  label: {
    color: "#38bdf8",
    fontSize: 12,
    marginBottom: 2,
    textTransform: "uppercase",
    letterSpacing: "0.05em",
  },
  mobileActions: {
    display: "flex",
    gap: 10,
    marginTop: 10,
  },

  editBtn: {
    background: "#38bdf8",
    border: "none",
    color: "#020617",
    padding: "6px 12px",
    borderRadius: 6,
    cursor: "pointer",
    fontWeight: 600,
    flex: 1,
  },
  deleteBtn: {
    background: "#ef4444",
    border: "none",
    color: "#fff",
    padding: "6px 12px",
    borderRadius: 6,
    cursor: "pointer",
    fontWeight: 600,
    flex: 1,
  },
  empty: {
    color: "#94a3b8",
    padding: "10px",
  },
};
